
const WORKER_NAME = "seo-render";

/** Add diagnostic headers so we can prove a response was generated by the Worker. */
function withDiagHeaders(baseHeaders, requestUrl, extra = {}) {
  const h = new Headers(baseHeaders || {});
  h.set("X-P55-Worker", WORKER_NAME);
  if (requestUrl) h.set("X-P55-URL", requestUrl);
  for (const [k, v] of Object.entries(extra || {})) {
    if (v !== undefined && v !== null && v !== "") h.set(String(k), String(v));
  }
  return h;
}
