// ---------------- Helpers ----------------

function slugify(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .slice(0, 80);
}

function escapeHtml(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatGBP(n) {
  const num = Number(String(n ?? "").replace(/[^\d.]/g, ""));
  if (!Number.isFinite(num)) return "";
  return new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "GBP",
    maximumFractionDigits: 0
  }).format(num);
}

function pickFirstPhoto(rec) {
  const photos = rec?.fields?.Photos;
  const first = Array.isArray(photos) ? photos[0] : null;
  return first?.url || "";
}

function getSlugFromRecord(rec) {
  const s = String(rec?.fields?.Slug || "").trim();
  if (s) return slugify(s);

  const mm = String(rec?.fields?.Make_Model || "").trim();
  const reg = String(rec?.fields?.Registration || "").trim();
  return slugify([mm, reg].filter(Boolean).join(" "));
}

function canonicalPathFor(rec) {
  const slug = getSlugFromRecord(rec) || "vehicle";
  return `/stock/${slug}-${rec.id}`;
}

function extractIdFromStockPath(pathname) {
  // Robust: extract an Airtable record id anywhere in the path.
  // Matches recXXXXXXXXXXXX style ids.
  const m = String(pathname || "").match(/rec[a-zA-Z0-9]{10,}/);
  return m ? m[0] : "";
}

async function fetchStockJson({ bypassCache = false } = {}) {
  // IMPORTANT:
  // Prefer the production routed endpoint (same zone) to avoid workers.dev edge-cases,
  // but fall back to workers.dev if needed.
  const origins = [CARS_API_PRIMARY, CARS_API_FALLBACK];

  let last = { ok: false, status: 0, text: "" };

  for (const origin of origins) {
    const apiUrl = new URL(origin);

    // cars-api caching is upstream; we only use this to de-stale in debugging.
    if (bypassCache) apiUrl.searchParams.set("__bust", String(Date.now()));

    const res = await fetch(apiUrl.toString(), {
      headers: {
        Accept: "application/json",
        "Cache-Control": bypassCache ? "no-cache" : "max-age=0"
      },
      cf: bypassCache ? { cacheTtl: 0, cacheEverything: false } : undefined
    }).catch(() => null);

    if (!res) {
      last = { ok: false, status: 0, text: "fetch_failed" };
      continue;
    }

    const text = await res.text().catch(() => "");

    if (!res.ok) {
      last = { ok: false, status: res.status, text };
      continue;
    }

    try {
      return { ok: true, json: JSON.parse(text), originUsed: origin };
    } catch {
      last = { ok: false, status: res.status, text };
      continue;
    }
  }

  return last;
}

function buildWhatsAppLink({ titleCore, canonicalUrl }) {
  const msg = `Hi Nathan, I'm interested in your ${titleCore}. Is it still available?\n\n${canonicalUrl}`;
  return `https://wa.me/${WHATSAPP_PHONE_E164}?text=${encodeURIComponent(msg)}`;
}

// --- Description formatting (server-side) ---
// Turns your Airtable Full_Description into premium HTML that matches your old UI style.
function descriptionToHtml(text) {
  const raw = (text || "").toString().replace(/\r/g, "").trim();
  if (!raw) return "";

  const lines = raw.split("\n");

  // Identify headings used in your copy
  const headingSet = new Set(["Highlights", "Specification", "Condition", "Why This Car Stands Out"]);
  let current = "opening";
  const sections = {
    opening: [],
    Highlights: [],
    Specification: [],
    Condition: [],
    "Why This Car Stands Out": []
  };

  for (const line0 of lines) {
    const line = line0.trim();
    if (!line) {
      if (current === "opening" && sections.opening.length) sections.opening.push(""); // preserve paragraph break
      continue;
    }

    if (headingSet.has(line)) {
      current = line;
      continue;
    }

    // bullets: •, -, *, etc
    const isBullet = /^[•\u2022\-\*]+\s+/.test(line);
    if (current === "opening") {
      sections.opening.push(line);
    } else {
      const cleaned = line.replace(/^[•\u2022\-\*]+\s*/, "").trim();
      if (!cleaned) continue;
      sections[current].push(cleaned);
    }
  }

  // Build intro paragraphs
  const opening = sections.opening.join("\n").trim();
  const introParas = opening
    ? opening.split(/\n\n+/).map(p => p.trim()).filter(Boolean)
    : [];

  const introHtml = introParas.length
    ? introParas.map(p => `<p>${escapeHtml(p).replaceAll("\n","<br>")}</p>`).join("")
    : "";

  const cardOrder = ["Highlights","Specification","Condition","Why This Car Stands Out"];
  const cards = cardOrder
    .map(k => ({ title: k, items: sections[k] }))
    .filter(c => c.items && c.items.length);

  const cardsHtml = cards.length
    ? `<div class="vehicle-desc-sections">${
        cards.map(c => `
          <section class="vehicle-desc-card">
            <h2>${escapeHtml(c.title)}</h2>
            <ul>${c.items.map(i => `<li>${escapeHtml(i)}</li>`).join("")}</ul>
          </section>
        `).join("")
      }</div>`
    : "";

  return `${introHtml}${cardsHtml}`;
}

function injectBetweenTags(html, id, tag, innerHtml) {
  // Replaces: <tag ... id="id" ...>...</tag> with supplied innerHtml
  const re = new RegExp(`<${tag}([^>]*\sid="${id}"[^>]*)>([\s\S]*?)</${tag}>`, "i");
  if (!re.test(html)) return html;
  return html.replace(re, `<${tag}$1>${innerHtml}</${tag}>`);
}

function setAttrOnId(html, id, attr, value) {
  // Sets/overwrites an attribute on the first element with id="id"
  const re = new RegExp(`(<[^>]+\sid="${id}"[^>]*)(>)`, "i");
  const m = html.match(re);
  if (!m) return html;

  let start = m[1];
  const end = m[2];

  const attrRe = new RegExp(`\s${attr}="[^"]*"`, "i");
  if (attrRe.test(start)) {
    start = start.replace(attrRe, ` ${attr}="${escapeHtml(value)}"`);
  } else {
    start = start + ` ${attr}="${escapeHtml(value)}"`;
  }
  return html.replace(re, start + end);
}

function upsertMeta(html, name, content) {
  const safe = escapeHtml(content);
  const re = new RegExp(`<meta\s+name="${name}"\s+content="[^"]*"\s*/?>`, "i");
  if (re.test(html)) return html.replace(re, `<meta name="${name}" content="${safe}">`);
  return html.replace("</title>", `</title>\n    <meta name="${name}" content="${safe}">`);
}

function upsertCanonical(html, canonicalUrl) {
  const safe = escapeHtml(canonicalUrl);
  const re = /<link\s+rel="canonical"\s+href="[^"]*"\s*\/?>/i;
  if (re.test(html)) return html.replace(re, `<link rel="canonical" href="${safe}">`);
  return html.replace("</title>", `</title>\n    <link rel="canonical" href="${safe}">`);
}

function upsertOg(html, prop, content) {
  const safe = escapeHtml(content);
  const re = new RegExp(`<meta\s+property="${prop}"\s+content="[^"]*"\s*/?>`, "i");
  if (re.test(html)) return html.replace(re, `<meta property="${prop}" content="${safe}">`);
  return html.replace("</title>", `</title>\n    <meta property="${prop}" content="${safe}">`);
}

function safeJsonForScriptTag(json) {
  // Keep JSON valid while preventing accidental </script> termination.
  // We *do not* HTML-escape quotes, otherwise JSON-LD becomes invalid.
  return String(json)
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}

function upsertJsonLd(html, jsonObject) {
  const json = safeJsonForScriptTag(JSON.stringify(jsonObject));

  const SCRIPT_OPEN = '<script type="application/ld+json" data-p55-seo="1">';
  const SCRIPT_CLOSE = '</script>';
  const block = SCRIPT_OPEN + json + SCRIPT_CLOSE;

  // Remove any previous P55 JSON-LD block then insert once (idempotent).
  html = html.replace(/<script[^>]*data-p55-seo="1"[^>]*>[\s\S]*?<\/script>\s*/i, "");

  if (/<\/head>/i.test(html)) {
    return html.replace(/<\/head>/i, block + "\n</head>");
  }
  return block + "\n" + html;
}

function buildVehicleSchema(rec, canonicalUrl) {
  const f = rec.fields || {};
  const makeModel = String(f.Make_Model || "").trim();
  const reg = String(f.Registration || "").trim();
  const price = Number(String(f.Price ?? "").replace(/[^\d.]/g, ""));
  const mileage = Number(String(f.Mileage ?? "").replace(/[^\d.]/g, ""));

  const images = Array.isArray(f.Photos)
    ? f.Photos.map(p => p?.url).filter(Boolean).slice(0, 10)
    : [];

  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "AutoDealer",
        "@id": `${canonicalUrl}#dealer`,
        "name": "Project 55 Motors",
        "url": CANONICAL_ORIGIN,
        "areaServed": "GB",
        "address": {
          "@type": "PostalAddress",
          "addressLocality": "Cleobury Mortimer",
          "addressRegion": "Shropshire",
          "addressCountry": "GB"
        }
      },
      {
        "@type": "Vehicle",
        "@id": `${canonicalUrl}#vehicle`,
        "name": [makeModel, reg].filter(Boolean).join(" • "),
        "image": images.length ? images : undefined,
        "mileageFromOdometer": Number.isFinite(mileage)
          ? { "@type": "QuantitativeValue", "value": Math.round(mileage), "unitCode": "SMI" }
          : undefined,
        "fuelType": f.Fuel_type || undefined,
        "vehicleTransmission": f.Transmission || undefined,
        "offers": Number.isFinite(price)
          ? {
              "@type": "Offer",
              "priceCurrency": "GBP",
              "price": Math.round(price),
              "availability": "https://schema.org/InStock",
              "url": canonicalUrl,
              "seller": { "@id": `${canonicalUrl}#dealer` }
            }
          : undefined
      }
    ]
  };
}

function renderVehiclePage(rec) {
  const f = rec.fields || {};
  const makeModel = String(f.Make_Model || "").trim() || "Vehicle";
  const reg = String(f.Registration || "").trim();
  const titleCore = reg ? `${makeModel} (${reg})` : makeModel;

  const canonicalUrl = CANONICAL_ORIGIN + canonicalPathFor(rec);
  const ogImage = pickFirstPhoto(rec);
  const price = formatGBP(f.Price);

  const shortDesc = String(f.Short_Description || "").trim();
  const fullDesc = String(f.Full_Description || "").trim();
  const metaDesc = (shortDesc || fullDesc || "View full specification, photos, and enquiry options at Project 55 Motors.")
    .replace(/\s+/g, " ")
    .slice(0, 155);

  // Start from premium template
  let html = VEHICLE_TEMPLATE_HTML;

  // Head: title, canonical, meta, og, schema
  html = html.replace(/<title>[\s\S]*?<\/title>/i, `<title>${escapeHtml(titleCore)} | Project 55 Motors</title>`);
  html = upsertMeta(html, "description", metaDesc);
  html = upsertCanonical(html, canonicalUrl);
  html = upsertOg(html, "og:title", `${titleCore} | Project 55 Motors`);
  html = upsertOg(html, "og:description", metaDesc);
  html = upsertOg(html, "og:url", canonicalUrl);
  if (ogImage) html = upsertOg(html, "og:image", ogImage);

  const schema = buildVehicleSchema(rec, canonicalUrl);
  html = upsertJsonLd(html, schema);

  // Body injections into the existing premium DOM:
  html = injectBetweenTags(html, "vehicle-title", "h1", escapeHtml(makeModel));
  html = injectBetweenTags(html, "vehicle-price", "p", escapeHtml(price));
  html = injectBetweenTags(html, "vehicle-reg", "p", reg ? escapeHtml(`Registration: ${reg}`) : "");

  const descHtml = descriptionToHtml(fullDesc || shortDesc);
  html = injectBetweenTags(html, "vehicle-description", "div", descHtml);

  // WhatsApp: update href on existing floating button and any inline button
  const waLink = buildWhatsAppLink({ titleCore: makeModel + (reg ? ` (${reg})` : ""), canonicalUrl });
  html = setAttrOnId(html, "whatsapp-btn", "href", waLink);

  // Also set enquire button to go to contact with context (optional, safe)
  html = setAttrOnId(html, "enquire-btn", "onclick", "location.href='/contact';");

  // Provide record data for the existing /vehicle.js (so it doesn't need to refetch)
  const boot = `<script>window.__P55_VEHICLE__=${JSON.stringify({ id: rec.id, fields: f })};</script>`;
  html = html.replace("</body>", `${boot}\n</body>`);

  return html;
}

function buildSitemapXml(urls) {
  const esc = (s) => escapeHtml(s);
  const lines = [];
  lines.push(`<?xml version="1.0" encoding="UTF-8"?>`);
  lines.push(`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">`);
  for (const u of urls) {
    lines.push(`  <url>`);
    lines.push(`    <loc>${esc(u.loc)}</loc>`);
    lines.push(`  </url>`);
  }
  lines.push(`</urlset>`);
  return lines.join("\n");
}


function jsonResponse(obj, status = 200, headers = {}, requestUrl = "") {
  const h = withDiagHeaders({ "Content-Type": "application/json; charset=utf-8", ...headers }, requestUrl, { "X-P55-Mode": "json" });
  return new Response(JSON.stringify(obj, null, 2), { status, headers: h });
}

export default {
  async fetch(request) {
    try {
    const url = new URL(request.url);
    const path = url.pathname;

    // Debug: verify cars-api connectivity and record visibility
    if (path === "/__seo_debug") {
      const wantId = url.searchParams.get("id") || "";
      const stock = await fetchStockJson({ bypassCache: true });
      if (!stock.ok) return jsonResponse({ ok: false, status: stock.status || 0, sample: (stock.text || "").slice(0, 800) }, 502, { "Cache-Control": "no-store" });
      const records = Array.isArray(stock.json?.records) ? stock.json.records : [];
      return jsonResponse({
        ok: true,
        carsApiRecords: records.length,
        firstIds: records.slice(0, 10).map(r => r?.id).filter(Boolean),
        sampleFieldKeys: records[0]?.fields ? Object.keys(records[0].fields).slice(0, 25) : []
      }, 200, { "Cache-Control": "no-store" });
    }

    // 1) Dynamic sitemap
    if (path === "/sitemap.xml") {
      const stockRes = await fetchStockJson();
      if (!stockRes.ok) return new Response("Sitemap unavailable", { status: 503 });

      const records = Array.isArray(stockRes.json?.records) ? stockRes.json.records : [];
      const urls = [
        { loc: `${CANONICAL_ORIGIN}/` },
        { loc: `${CANONICAL_ORIGIN}/inventory` },
        { loc: `${CANONICAL_ORIGIN}/about` },
        { loc: `${CANONICAL_ORIGIN}/contact` }
      ];
      for (const rec of records) urls.push({ loc: `${CANONICAL_ORIGIN}${canonicalPathFor(rec)}` });

      return new Response(buildSitemapXml(urls), {
        headers: withDiagHeaders({ "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "no-store" }, request.url, { "X-P55-Mode": "sitemap" })
      });
    }

    // 2) Legacy route: /vehicle?id=recXXXX -> 301 canonical
    if (path === "/vehicle") {
      const id = url.searchParams.get("id");
      if (!id) return fetch(request);

      // During rollout, never let an edge/browser cache "the wrong" redirect.
      // Also bypass cache when resolving, so newly-added/edited cars resolve immediately.
      const stockRes = await fetchStockJson({ bypassCache: true });
      if (!stockRes.ok) {
        return new Response("Not found", {
          status: 404,
          headers: { "Cache-Control": "no-store" }
        });
      }

      const records = Array.isArray(stockRes.json?.records) ? stockRes.json.records : [];
      const rec = records.find(r => r?.id === id);
      if (!rec) {
        return new Response("Not found", {
          status: 404,
          headers: { "Cache-Control": "no-store" }
        });
      }

      const location = CANONICAL_ORIGIN + canonicalPathFor(rec);
      return new Response(null, {
        status: 302,
        headers: {
          Location: location,
          "Cache-Control": "no-store, max-age=0",
          "CDN-Cache-Control": "no-store, max-age=0"
        }
      });
    }

    // 3) Canonical SSR stock pages
    if (path.startsWith("/stock/")) {
      if (path === "/stock" || path === "/stock/") return fetch(request);

      const id = extractIdFromStockPath(path);
      if (!id) return new Response("Not found", { status: 404 });

      const stockRes = await fetchStockJson();
      if (!stockRes.ok) return new Response("Not found", { status: 404 });

      const records = Array.isArray(stockRes.json?.records) ? stockRes.json.records : [];
      const rec = records.find(r => r?.id === id);
      if (!rec) return new Response("Not found", { status: 404 });

      const canonical = CANONICAL_ORIGIN + canonicalPathFor(rec);
      if (CANONICAL_ORIGIN + path !== canonical) return new Response(null, {
        status: 301,
        headers: {
          "Location": canonical,
          "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"
        }
      });
const html = renderVehiclePage(rec);
      return new Response(html, {
        headers: withDiagHeaders({ "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" }, request.url, { "X-P55-Mode": "stock" })
      });
    }

    // Anything else: let static site handle it
    return fetch(request);
    } catch (err) {
      // Fail-open: never take the site down due to SSR errors.
      // We fall back to origin (or static asset) as-is.
      try {
        return fetch(request);
      } catch (e2) {
        return new Response('Edge error', { status: 502 });
      }
    }
  }
};